function hasValidRequisitionId(job) {
  var id = job ? job.Id : undefined;
  return id !== undefined && id !== null && String(id).trim() !== '';
}
function dedupeById(jobs) {
  var map = new Map();
  var missingIdCounter = 0;
  for (var i = 0; i < jobs.length; i++) {
    var job = jobs[i];
    var key = hasValidRequisitionId(job) ? ('id:' + String(job.Id)) : ('missing:' + (missingIdCounter++));
    map.set(key, job);
  }
  return Array.from(map.values());
}
function validRequisitionIds(jobs) {
  var ids = new Set();
  for (var i = 0; i < jobs.length; i++) {
    if (hasValidRequisitionId(jobs[i])) ids.add(String(jobs[i].Id));
  }
  return ids;
}
function mergeIncludesEveryValidId(priorJobs, newJobs, merged) {
  var expected = validRequisitionIds(priorJobs);
  validRequisitionIds(newJobs).forEach(function (id) { expected.add(id); });
  var actual = validRequisitionIds(merged);
  var ok = true;
  expected.forEach(function (id) { if (!actual.has(id)) ok = false; });
  if (!ok) return false;
  return !(merged.length === 0 && (priorJobs.length > 0 || newJobs.length > 0));
}

const allInputItems = $input.all();
if (allInputItems.length !== 1) {
  throw new Error('Prepare Oracle HCM Page State expected exactly 1 input item but received ' + allInputItems.length + ' — refusing to process via $input.first() only, which would silently discard the rest.');
}
const input = allInputItems[0].json;
const feedUrl = $('Split Out Sources').item.json.feed_url;
const siteMatch = typeof feedUrl === 'string' ? feedUrl.match(/^https:\/\/([^/]+)\/hcmRestApi.*siteNumber=([A-Za-z0-9_]+)/) : null;
const candidateSiteUrl = siteMatch ? ('https://' + siteMatch[1] + '/hcmUI/CandidateExperience/en/sites/' + siteMatch[2]) : null;

const items = input.items;
const first = (Array.isArray(items) && items.length > 0) ? items[0] : null;
const offset = first ? first.Offset : undefined;
const limit = first ? first.Limit : undefined;
const totalJobsCount = first ? first.TotalJobsCount : undefined;
const requisitionList = first ? first.requisitionList : undefined;
const metaOk = typeof offset === 'number' && Number.isFinite(offset)
  && typeof limit === 'number' && Number.isFinite(limit)
  && typeof totalJobsCount === 'number' && Number.isFinite(totalJobsCount)
  && Array.isArray(requisitionList);

if (!metaOk) {
  return [{ json: { pageState: { rawJobs: [], pageOffset: 0, pageLimit: 0, totalJobsCount: 0, pagesFetched: 1, paginationIncomplete: true, isComplete: false, candidateSiteUrl: candidateSiteUrl, feedUrl: feedUrl } } }];
}

const stamped = requisitionList.map(function (job) { return Object.assign({}, job, { candidateSiteUrl: candidateSiteUrl }); });
const deduped = dedupeById(stamped);
if (!mergeIncludesEveryValidId([], stamped, deduped)) {
  return [{ json: { pageState: { rawJobs: [], pageOffset: 0, pageLimit: 0, totalJobsCount: 0, pagesFetched: 1, paginationIncomplete: true, isComplete: false, candidateSiteUrl: candidateSiteUrl, feedUrl: feedUrl } } }];
}

const isComplete = (offset + requisitionList.length) >= totalJobsCount;
return [{ json: { pageState: { rawJobs: deduped, pageOffset: offset, pageLimit: limit, totalJobsCount: totalJobsCount, pagesFetched: 1, paginationIncomplete: false, isComplete: isComplete, candidateSiteUrl: candidateSiteUrl, feedUrl: feedUrl } } }];

function hasValidRequisitionId(job) {
  var id = job ? job.Id : undefined;
  return id !== undefined && id !== null && String(id).trim() !== '';
}
function dedupeById(jobs) {
  var map = new Map();
  var missingIdCounter = 0;
  for (var i = 0; i < jobs.length; i++) {
    var job = jobs[i];
    var key = hasValidRequisitionId(job) ? ('id:' + String(job.Id)) : ('missing:' + (missingIdCounter++));
    map.set(key, job);
  }
  return Array.from(map.values());
}
function validRequisitionIds(jobs) {
  var ids = new Set();
  for (var i = 0; i < jobs.length; i++) {
    if (hasValidRequisitionId(jobs[i])) ids.add(String(jobs[i].Id));
  }
  return ids;
}
function mergeIncludesEveryValidId(priorJobs, newJobs, merged) {
  var expected = validRequisitionIds(priorJobs);
  validRequisitionIds(newJobs).forEach(function (id) { expected.add(id); });
  var actual = validRequisitionIds(merged);
  var ok = true;
  expected.forEach(function (id) { if (!actual.has(id)) ok = false; });
  if (!ok) return false;
  return !(merged.length === 0 && (priorJobs.length > 0 || newJobs.length > 0));
}

const allInputItems = $input.all();
if (allInputItems.length !== 1) {
  throw new Error('Merge & Classify Oracle HCM Page expected exactly 1 input item but received ' + allInputItems.length + ' — refusing to process via $input.first() only, which would silently discard the rest.');
}
const input = allInputItems[0].json;
const prior = input.pageState;

if (input.error) {
  return [{ json: Object.assign({}, input, { pageState: Object.assign({}, prior, { paginationIncomplete: true, isComplete: false }) }) }];
}

const items = input.items;
const first = (Array.isArray(items) && items.length > 0) ? items[0] : null;
const offset = first ? first.Offset : undefined;
const limit = first ? first.Limit : undefined;
const totalJobsCount = first ? first.TotalJobsCount : undefined;
const requisitionList = first ? first.requisitionList : undefined;
const metaOk = typeof offset === 'number' && Number.isFinite(offset)
  && typeof limit === 'number' && Number.isFinite(limit)
  && typeof totalJobsCount === 'number' && Number.isFinite(totalJobsCount)
  && Array.isArray(requisitionList);

if (!metaOk) {
  return [{ json: Object.assign({}, input, { pageState: Object.assign({}, prior, { paginationIncomplete: true, isComplete: false }) }) }];
}

const isNonAdvancingOffset = offset <= prior.pageOffset;
const isPrematureEmptyPage = requisitionList.length === 0 && offset < totalJobsCount;
if (isNonAdvancingOffset || isPrematureEmptyPage) {
  return [{ json: Object.assign({}, input, { pageState: Object.assign({}, prior, { paginationIncomplete: true, isComplete: false }) }) }];
}

const stamped = requisitionList.map(function (job) { return Object.assign({}, job, { candidateSiteUrl: prior.candidateSiteUrl }); });
const merged = dedupeById(prior.rawJobs.concat(stamped));
if (!mergeIncludesEveryValidId(prior.rawJobs, stamped, merged)) {
  return [{ json: Object.assign({}, input, { pageState: Object.assign({}, prior, { paginationIncomplete: true, isComplete: false }) }) }];
}

const isComplete = (offset + requisitionList.length) >= totalJobsCount;
return [{ json: Object.assign({}, input, { pageState: { rawJobs: merged, pageOffset: offset, pageLimit: limit, totalJobsCount: totalJobsCount, pagesFetched: prior.pagesFetched + 1, paginationIncomplete: false, isComplete: isComplete, candidateSiteUrl: prior.candidateSiteUrl, feedUrl: prior.feedUrl } }) }];

